// Service worker: makes Repwerk work offline. Generated by build.py from src/sw.template.js.
const CACHE = 'repwerk-ceda2f031b';
const SHELL = ['./', 'index.html', 'manifest.webmanifest', 'legal/anbieter.js', 'fonts/figtree.woff', 'fonts/archivo-display.woff', 'icons/icon-192.png', 'icons/icon-512.png', 'icons/apple-touch-icon.png', 'icons/favicon.png'];

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('repwerk-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.pathname.includes('/api/')) return;
  // Pages: network first, so new versions show up; offline falls back to the cached app.
  if (req.mode === 'navigate') {
    const isApp = url.origin === location.origin && /\/(index\.html)?$/.test(url.pathname);
    e.respondWith(fetch(req).then((res) => { if (isApp && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('index.html', copy)); } return res; }).catch(() => caches.match(isApp ? 'index.html' : req).then((hit) => hit || caches.match('index.html'))));
    return;
  }
  // Only our own files and stored workout photos are cached; other servers (Open Food Facts, CDNs) always go to the network.
  if (url.origin !== location.origin && !url.pathname.includes('/storage/v1/object/public/')) return;
  // Everything else (icons, fonts): cache first, then network.
  e.respondWith(caches.match(req).then((hit) => hit || fetch(req).then((res) => { if (res.ok || res.type === 'opaque') { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); } return res; })));
});
